import Foundation
import Testing
import KhaytCore
@testable import KhaytApp

/// Khayt as a printer in the slicer: the two OctoPrint routes a slicer's
/// "Send" uses (`LanServer+SlicerUpload`), through a real listener — the body
/// is streamed to disk, so a test that skipped the socket would skip the part
/// most likely to be wrong.
@MainActor
struct LanSlicerUploadTests {

    static let key = "0123456789ABCDEF0123456789ABCDEF"

    /// An Orca-style G-code: its summary at the head, as Orca writes it.
    static let gcode = """
        ; generated by OrcaSlicer 2.3.0
        ; estimated printing time (normal mode) = 2h 5m 0s
        ; filament used [g] = 37.25
        ; filament_type = PETG
        G28
        G1 X10 Y10 Z0.2 F3000
        G1 X20 Y10 E1.2
        """

    final class Box: @unchecked Sendable {
        var root: URL
        var received: [(URL, String)] = []
        init(_ root: URL) { self.root = root }
    }

    /// A started server whose inbox is a scratch folder, filed by the app's
    /// own `fileSlicerUpload` so the figures are read as the app reads them.
    static func bench(key: String? = LanSlicerUploadTests.key, maxBytes: Int = LanServer.maxInflate)
        async throws -> (server: LanServer, port: UInt16, box: Box) {
        let shop = Shop()
        await shop.load(.sample)
        let engine = try #require(shop.engine)
        let root = FileManager.default.temporaryDirectory
            .appending(path: "khayt-slicer-test-\(UUID().uuidString)", directoryHint: .isDirectory)
        let box = Box(root)
        let book = shop.lanBook
        var host = LanServer.Host(store: { book }, pin: "24682468", engine: engine)
        host.slicerKey = { key }
        host.slicerMaxBytes = maxBytes
        host.slicerScratch = SlicerInbox.incoming(root: root)
        host.slicerReceive = { file, name in
            _ = try await Shop.fileSlicerUpload(file, name: name, root: box.root, engine: engine)
        }
        let server = LanServer(host: host)
        let port = try await server.start(port: 0, bind: .loopback)
        return (server, port, box)
    }

    struct Reply { let status: Int; let body: Data
                   var text: String { String(decoding: body, as: UTF8.self) }
                   var json: [String: Any] { (try? JSONSerialization.jsonObject(with: body)) as? [String: Any] ?? [:] } }

    static func send(_ port: UInt16, _ path: String, method: String = "GET", key: String? = nil,
                     body: Data? = nil, contentType: String? = nil) async throws -> Reply {
        var request = URLRequest(url: URL(string: "http://127.0.0.1:\(port)\(path)")!)
        request.httpMethod = method
        if let key { request.setValue(key, forHTTPHeaderField: "X-Api-Key") }
        if let contentType { request.setValue(contentType, forHTTPHeaderField: "Content-Type") }
        request.httpBody = body
        let (data, response) = try await LanServerTests.NoRedirect.session.data(for: request)
        let http = try #require(response as? HTTPURLResponse)
        return Reply(status: http.statusCode, body: data)
    }

    /// A slicer's multipart body: the file, and PrusaSlicer's `print`/`path` fields.
    static func multipart(name: String, contents: String, print: Bool = false) -> (Data, String) {
        let boundary = "------------------------khayt\(UUID().uuidString.prefix(8))"
        var body = Data()
        func add(_ s: String) { body.append(Data(s.utf8)) }
        add("--\(boundary)\r\nContent-Disposition: form-data; name=\"print\"\r\n\r\n\(print ? "true" : "false")\r\n")
        add("--\(boundary)\r\nContent-Disposition: form-data; name=\"path\"\r\n\r\n\r\n")
        add("--\(boundary)\r\nContent-Disposition: form-data; name=\"file\"; filename=\"\(name)\"\r\n")
        add("Content-Type: application/octet-stream\r\n\r\n\(contents)\r\n--\(boundary)--\r\n")
        return (body, "multipart/form-data; boundary=\(boundary)")
    }

    @Test("GET /api/version answers as OctoPrint, so a slicer's Test passes")
    func versionAnswers() async throws {
        let b = try await Self.bench()
        defer { b.server.stop() }
        let reply = try await Self.send(b.port, "/api/version", key: Self.key)
        #expect(reply.status == 200)
        #expect(reply.json["api"] as? String == "0.1")
        #expect(reply.json["server"] as? String == "1.10.0")
        #expect((reply.json["text"] as? String)?.hasPrefix("OctoPrint") == true,
                "PrusaSlicer and its forks only accept a host whose text starts with OctoPrint")
    }

    @Test("no key is 401 and a wrong key is 403, on both routes, and nothing is filed")
    func keyIsChecked() async throws {
        let b = try await Self.bench()
        defer { b.server.stop() }
        #expect(try await Self.send(b.port, "/api/version").status == 401)
        #expect(try await Self.send(b.port, "/api/version", key: "WRONG").status == 403)
        let (body, type) = Self.multipart(name: "plate.gcode", contents: Self.gcode)
        #expect(try await Self.send(b.port, "/api/files/local", method: "POST", body: body, contentType: type).status == 401)
        #expect(try await Self.send(b.port, "/api/files/local", method: "POST", key: "WRONG",
                                    body: body, contentType: type).status == 403)
        #expect(SlicerInbox.list(root: b.box.root).isEmpty)
    }

    @Test("ten wrong keys lock the visitor out of the slicer routes")
    func wrongKeysLockOut() async throws {
        let b = try await Self.bench()
        defer { b.server.stop() }
        for _ in 0..<10 { _ = try await Self.send(b.port, "/api/version", key: "WRONG") }
        #expect(try await Self.send(b.port, "/api/version", key: Self.key).status == 429)
    }

    @Test("an upload lands in the inbox with the slicer's grams and time read off it")
    func uploadLandsWithFigures() async throws {
        let b = try await Self.bench()
        defer { b.server.stop(); try? FileManager.default.removeItem(at: b.box.root) }
        let (body, type) = Self.multipart(name: "Benchy_PETG.gcode", contents: Self.gcode)
        let reply = try await Self.send(b.port, "/api/files/local", method: "POST", key: Self.key,
                                        body: body, contentType: type)
        #expect(reply.status == 201)
        #expect(reply.json["done"] as? Bool == true)
        let local = (reply.json["files"] as? [String: Any])?["local"] as? [String: Any]
        #expect(local?["name"] as? String == "Benchy_PETG.gcode")
        #expect(local?["origin"] as? String == "local")
        #expect((local?["refs"] as? [String: Any])?["resource"] as? String != nil)

        let items = SlicerInbox.list(root: b.box.root)
        let item = try #require(items.first)
        #expect(items.count == 1)
        #expect(item.name == "Benchy_PETG.gcode")
        #expect(item.grams == 37.25)
        #expect(item.minutes == 125)
        let stored = try String(contentsOf: SlicerInbox.file(of: item, root: b.box.root), encoding: .utf8)
        #expect(stored == Self.gcode, "the file part was not stored byte for byte")
        // The spooled body is gone once answered.
        let left = (try? FileManager.default.contentsOfDirectory(atPath: SlicerInbox.incoming(root: b.box.root).path)) ?? []
        #expect(left.isEmpty, Comment(rawValue: "scratch left behind: \(left)"))
    }

    @Test("print=true is never acted on, and the answer says so")
    func printIsIgnored() async throws {
        let b = try await Self.bench()
        defer { b.server.stop(); try? FileManager.default.removeItem(at: b.box.root) }
        let (body, type) = Self.multipart(name: "plate.gcode", contents: Self.gcode, print: true)
        let reply = try await Self.send(b.port, "/api/files/local", method: "POST", key: Self.key,
                                        body: body, contentType: type)
        #expect(reply.status == 201)
        #expect(reply.json["effectivePrint"] as? Bool == false)
        #expect(reply.json["effectiveSelect"] as? Bool == false)
        // Filed, and only filed: the host has no way to reach a printer at
        // all, and the file waits in the inbox for the shop.
        #expect(SlicerInbox.list(root: b.box.root).count == 1)
    }

    @Test("a body over the cap is refused 413 from its head, before it is read")
    func tooLargeIsRefused() async throws {
        let b = try await Self.bench(maxBytes: 4096)
        defer { b.server.stop() }
        let port = b.port
        let head = "POST /api/files/local HTTP/1.1\r\nHost: 127.0.0.1\r\nX-Api-Key: \(Self.key)\r\n"
            + "Content-Type: multipart/form-data; boundary=x\r\nContent-Length: 5000000\r\n\r\n"
        let line = await offPool { Self.statusLine(port: port, send: head) }
        #expect(line.hasPrefix("HTTP/1.1 413"), Comment(rawValue: "answered \(line)"))
        #expect(SlicerInbox.list(root: b.box.root).isEmpty)
    }

    @Test("a file that is not G-code is refused 415")
    func wrongKindRefused() async throws {
        let b = try await Self.bench()
        defer { b.server.stop() }
        let (body, type) = Self.multipart(name: "model.stl", contents: "solid x\nendsolid x\n")
        let reply = try await Self.send(b.port, "/api/files/local", method: "POST", key: Self.key,
                                        body: body, contentType: type)
        #expect(reply.status == 415)
        #expect(SlicerInbox.list(root: b.box.root).isEmpty)
    }

    @Test("switched off, both routes are the ordinary 404")
    func offIsNotFound() async throws {
        let b = try await Self.bench(key: nil)
        defer { b.server.stop() }
        #expect(try await Self.send(b.port, "/api/version", key: Self.key).status == 404)
        let (body, type) = Self.multipart(name: "plate.gcode", contents: Self.gcode)
        #expect(try await Self.send(b.port, "/api/files/local", method: "POST", key: Self.key,
                                    body: body, contentType: type).status == 404)
        #expect(SlicerInbox.list(root: b.box.root).isEmpty)
    }

    @Test("the multipart reader finds each part, its name and its filename")
    func multipartParts() throws {
        let (body, type) = Self.multipart(name: "a b.gcode", contents: "G28\r\nG1")
        let boundary = try #require(Multipart.boundary(type))
        let parts = try #require(Multipart.parts(body, boundary: boundary))
        #expect(parts.map(\.name) == ["print", "path", "file"])
        let file = try #require(parts.last)
        #expect(file.filename == "a b.gcode")
        #expect(String(decoding: body[file.range], as: UTF8.self) == "G28\r\nG1")
        #expect(Multipart.boundary("application/json") == nil)
        #expect(Multipart.parts(Data("garbage".utf8), boundary: "x") == nil)
    }

    @Test("only sliced files are taken")
    func kinds() {
        #expect(LanServer.slicerFileTaken("a.gcode"))
        #expect(LanServer.slicerFileTaken("A.BGCODE"))
        #expect(LanServer.slicerFileTaken("plate.gcode.3mf"))
        #expect(!LanServer.slicerFileTaken("model.3mf"))
        #expect(!LanServer.slicerFileTaken("model.stl"))
    }

    /// Send `send`, return the first line of whatever comes back.
    nonisolated static func statusLine(port: UInt16, send: String) -> String {
        let fd = socket(AF_INET, SOCK_STREAM, 0)
        guard fd >= 0 else { return "no socket" }
        defer { close(fd) }
        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = port.bigEndian
        addr.sin_addr.s_addr = inet_addr("127.0.0.1")
        let ok = withUnsafePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        guard ok == 0 else { return "no connect" }
        let data = Data(send.utf8)
        _ = data.withUnsafeBytes { write(fd, $0.baseAddress, data.count) }
        var tv = timeval(tv_sec: Int(LanStallTests.patience), tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))
        var buf = [UInt8](repeating: 0, count: 512)
        let n = read(fd, &buf, 512)
        guard n > 0 else { return "nothing (\(n))" }
        return String(decoding: buf[0..<n], as: UTF8.self).components(separatedBy: "\r\n").first ?? ""
    }
}
